describe('Approval Rules -> XML to Fluent', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('Approval rules with default RuleSets and Due Date with action none', async () => {
        const project = ctx.createProject({})

        const xmlContent = loadTestFile(
            'sys_hub_flow_295fbe4a37bdb6100e11a3e734924bbd.xml',
            'core-actions/fluent/approval-rules/xmls'
        )
        const { changedFiles } = await project.transform({
            path: 'sys_hub_flow_295fbe4a37bdb6100e11a3e734924bbd.xml',
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getName()).toBe('sys_hub_flow_295fbe4a37bdb6100e11a3e734924bbd.now.ts')

        const content = changedFiles[0].getContent()

        expect(content).toContain(`record: wfa.dataPill(_params.trigger.current, 'reference')`)
        expect(content).toContain(`table: 'incident'`)
        expect(content).toContain(`approval_reason: 'sdsds'`)
        expect(content).toContain(`approval_field: 'approval'`)
        expect(content).toContain(`journal_field: 'approval_history'`)
        expect(content).toContain('approval_conditions: wfa.approvalRules({')
        expect(content).toContain(`conditionType: 'OR'`)
        expect(content).toContain('ruleSets: [')
        expect(content).toContain(`action: 'Approves'`)
        expect(content).toContain(`conditionType: 'AND'`)
        expect(content).toContain('rules: []')

        //Validate Due Date fields
        expect(content).toContain(`due_date: wfa.approvalDueDate`)
        expect(content).toContain(`action: 'none'`)
        expect(content).toContain(`dateType: 'actual'`)
        expect(content).toContain(`date: '{}'`)
        expect(content).toContain(`duration: 1`)
        expect(content).toContain(`durationType: 'days'`)
        expect(content).toContain(`daysSchedule: ''`)
    })

    test('Approval rules with multiple Rules Sets and rules containing OR conditions and Due Date with action approve with relative date', async () => {
        const project = ctx.createProject({})

        const xmlContent = loadTestFile(
            'sys_hub_flow_93932a4a37bd36100e11a3e734924ba5.xml',
            'core-actions/fluent/approval-rules/xmls'
        )
        const { changedFiles } = await project.transform({
            path: 'sys_hub_flow_93932a4a37bd36100e11a3e734924ba5.xml',
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getName()).toBe('sys_hub_flow_93932a4a37bd36100e11a3e734924ba5.now.ts')

        const content = changedFiles[0].getContent()

        expect(content).toContain(`wfa.dataPill(_params.trigger.current, 'reference')`)
        expect(content).toContain(`table: 'incident'`)
        expect(content).toContain(`approval_reason: 'sdsds'`)
        expect(content).toContain(`approval_field: 'approval'`)
        expect(content).toContain(`journal_field: 'approval_history'`)
        expect(content).toContain('approval_conditions: wfa.approvalRules({')
        expect(content).toContain(`conditionType: 'OR'`)
        expect(content).toContain('ruleSets: [')
        expect(content).toContain(`action: 'Approves'`)
        expect(content).toContain(`conditionType: 'AND'`)
        expect(content).toContain('rules: [')

        // Validate Due Date fields
        expect(content).toContain(`due_date: wfa.approvalDueDate`)
        expect(content).toContain(`action: 'approve'`)
        expect(content).toContain(`dateType: 'relative'`)
        expect(content).toContain(`date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time')`)
        expect(content).toContain(`duration: 15`)
        expect(content).toContain(`durationType: 'days'`)
        expect(content).toContain(`daysSchedule: '08fcd0830a0a0b2600079f56b1adb9ae'`)
    })

    test('Approval rules RuleSet with datapills for Approve action and Due Date with action = reject with actual date referencing trigger datapills', async () => {
        const project = ctx.createProject({})

        const xmlContent = loadTestFile(
            'ask-for-approval-due-date-with-action-reject-actual-date-example.xml',
            'core-actions/fluent/approval-rules/xmls'
        )
        const { changedFiles } = await project.transform({
            path: 'ask-for-approval-due-date-with-action-reject-actual-date-example.xml',
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getName()).toBe(
            'ask-for-approval-due-date-with-action-reject-actual-date-example.now.ts'
        )

        const content = changedFiles[0].getContent()

        expect(content).toContain(`wfa.dataPill(_params.trigger.current, 'reference')`)
        expect(content).toContain(`table: 'incident'`)
        expect(content).toContain(`approval_reason: 'Test 123'`)
        expect(content).toContain(`approval_field: 'approval'`)
        expect(content).toContain(`journal_field: 'approval_history'`)
        expect(content).toContain('approval_conditions: wfa.approvalRules({')
        expect(content).toContain(`conditionType: 'OR'`)
        expect(content).toContain('ruleSets: [')
        expect(content).toContain(`action: 'Approves'`)
        expect(content).toContain(`conditionType: 'AND'`)
        expect(content).toContain('rules: [')
        expect(content).toContain(`ruleType: 'Any'`)
        expect(content).toContain(`users: [wfa.dataPill(_params.trigger.current.assigned_to, 'reference')]`)
        expect(content).toContain(`groups: [wfa.dataPill(_params.trigger.current.assignment_group, 'reference')]`)
        expect(content).toContain('manual: false')

        // Validate Due Date fields
        expect(content).toContain(`due_date: wfa.approvalDueDate`)
        expect(content).toContain(`action: 'reject'`)
        expect(content).toContain(`dateType: 'actual'`)
        expect(content).toContain(`date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time')`)
        expect(content).toContain(`duration: 1`)
        expect(content).toContain(`durationType: 'days'`)
        expect(content).toContain(`daysSchedule: ''`)
    })
})
